import React from "react";

export default function MasonryGallery({ items = [] }) {
  return (
    <div className="masonry-gallery">
      {items.map((it, idx) => (
        <figure className="masonry-item" key={idx}>
          <img src={it.img} alt={it.title || `item-${idx}`} loading="lazy" />
          <figcaption>
            {it.price ? <span className="price">{it.price}</span> : null}
            <div className="masonry-meta">
              <h5>{it.title}</h5>
              {it.subtitle ? <p>{it.subtitle}</p> : null}
            </div>
          </figcaption>
        </figure>
      ))}
    </div>
  );
}
